style.css:
@-moz-document domain("google.com") {
/* colors you can swap */
:root {
  --my-bg: #061329;
  --my-blue: #087bff;
  --my-electric: #00aaff;
  --my-light: #80d5ff;
}

/* electric blue background */
html,
body {
  background:
    radial-gradient(ellipse at 50% 0%, #064b9b, transparent 55%),
    linear-gradient(145deg, #020817, #061b3c, #001638) fixed !important;
  color: #eaf5ff !important;
}

/* search bar */
form[role="search"] {
  background: #071a36 !important;
  border: 1px solid var(--my-blue) !important;
  border-radius: 30px !important;
  box-shadow: 0 0 20px #087bff66 !important;
}

/* search tabs */
[role="navigation"] a {
  border-radius: 25px !important;
  padding: 8px 14px !important;
  transition: 0.2s ease !important;
}

[role="navigation"] a:hover {
  background: #087bff44 !important;
  box-shadow: 0 0 15px #00aaff88 !important;
}

/* active tab accents */
[aria-current="page"] {
  color: #00aaff !important;
  border-bottom: 3px solid #00aaff !important;
}

/* buttons */
button,
input[type="submit"] {
  background: linear-gradient(135deg, #086cff, #00aaff) !important;
  color: white !important;
  border: 1px solid #168bff !important;
  border-radius: 20px !important;
}

/* links */
a {
  color: #70caff !important;
}

a:hover {
  color: white !important;
  text-shadow: 0 0 9px #00aaff !important;
}

/* result cards */
.MjjYud {
  border-radius: 16px !important;
  padding: 12px !important;
}

.MjjYud:hover {
  background: #087bff18 !important;
}

/* input fields */
input {
  color: white !important;
  caret-color: #00aaff !important;
}

/* selection */
::selection {
  background: #087bff !important;
  color: white !important;
}

/* scrollbar */
::-webkit-scrollbar-thumb {
  background: linear-gradient(#087bff, #00c3ff) !important;
  border-radius: 20px !important;
}
}
